'use strict';

// All Discord content is escaped before template insertion. The API capability is
// local to this window; bot credentials are held in memory and never persisted.
const $ = (selector,root=document)=>root.querySelector(selector);
const $$ = (selector,root=document)=>[...root.querySelectorAll(selector)];
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const keyHash=location.hash.slice(1),apiKey=keyHash.startsWith('key=')?new URLSearchParams(keyHash).get('key'):decodeURIComponent(keyHash);
// The fragment contains only the per-launch local capability, never the bot
// token. Keeping it permits a normal window refresh without persistent storage.
const titles={overview:'نظرة عامة',channels:'الأقسام والقنوات',roles:'الرتب والصلاحيات',redesign:'تصميم السيرفر',permissions:'فحص الصلاحيات',logs:'سجل النشاط',settings:'إعدادات الاتصال'};
const permissionNames={ViewChannel:'عرض القنوات',SendMessages:'إرسال الرسائل',ReadMessageHistory:'قراءة سجل الرسائل',AddReactions:'إضافة تفاعلات',EmbedLinks:'تضمين الروابط',AttachFiles:'إرفاق الملفات',Connect:'دخول القنوات الصوتية',Speak:'التحدث صوتيًا',MoveMembers:'نقل الأعضاء صوتيًا',ManageMessages:'إدارة الرسائل',ManageChannels:'إدارة القنوات',ManageRoles:'إدارة الرتب',ManageGuild:'إدارة السيرفر',ViewAuditLog:'عرض سجل التدقيق',Administrator:'مدير كامل',KickMembers:'طرد الأعضاء',BanMembers:'حظر الأعضاء',ModerateMembers:'إسكات الأعضاء مؤقتًا',ManageNicknames:'إدارة الأسماء المستعارة',ChangeNickname:'تغيير الاسم المستعار',MentionEveryone:'منشن الجميع',CreateInstantInvite:'إنشاء دعوة',ManageWebhooks:'إدارة Webhooks',ManageThreads:'إدارة المواضيع',CreatePublicThreads:'إنشاء مواضيع عامة',CreatePrivateThreads:'إنشاء مواضيع خاصة',SendMessagesInThreads:'إرسال رسائل في المواضيع',ManageEvents:'إدارة الفعاليات',CreateEvents:'إنشاء فعاليات',ManageGuildExpressions:'إدارة التعبيرات',UseExternalEmojis:'إيموجي خارجية',UseExternalStickers:'ملصقات خارجية',MuteMembers:'كتم الأعضاء صوتيًا',DeafenMembers:'إسكات الصوت للأعضاء',Stream:'بث مباشر',UseVAD:'استخدام النشاط الصوتي',PrioritySpeaker:'أولوية التحدث',RequestToSpeak:'طلب التحدث',UseApplicationCommands:'استخدام أوامر التطبيقات',SendVoiceMessages:'إرسال رسائل صوتية'};
const model={page:'overview',state:{version:'6.0',busy:false,logs:[]},config:{token:'',guildId:''},editor:null,query:'',tab:'general',overwriteRole:'',reviewSignature:null,awaitingEdit:false,lastEditHash:null,lastInventory:'',lastStateSignature:'',pending:false,runningAction:null,loaded:false,connectionError:false,rebuildRead:false};
let polling=false;

function inventory(){if(model.credentialsDirty)return null;const inv=model.state.inventory??model.state.diagnostics?.inventory??null;return inv&&model.config.guildId&&String(inv.guildId)!==model.config.guildId?null:inv;}
function busy(){return !!model.state.busy||model.pending;}
function online(){const s=model.state.presence?.status??model.state.online;return s===true||s==='online'||s==='ready'||s==='connected'||s?.status==='online';}
function guildId(){return String(model.config.guildId||inventory()?.guildId||model.state.diagnostics?.guildId||'');}
function guildName(){return inventory()?.guildName??(model.config.guildId?'السيرفر المحدد':'اختر سيرفرك');}
function colorHex(value){return '#'+Math.max(0,Number(value)||0).toString(16).padStart(6,'0').slice(-6);}
function shortTime(value){try{return new Date(value??Date.now()).toLocaleTimeString('ar-JO',{hour:'2-digit',minute:'2-digit'});}catch{return 'الآن';}}
function permissionLabel(name){return permissionNames[name]??name.replace(/([a-z])([A-Z])/g,'$1 $2');}
function typeLabel(type){return ({0:'قناة نصية',2:'قناة صوتية',4:'قسم'})[type]??'قناة';}
function typeIcon(type){return type===2?'voice':type===4?'folder':'hash';}
function toast(message,type='info'){const node=document.createElement('div');node.className='toast '+type;node.innerHTML=icon(type==='success'?'check':'info')+`<span>${esc(message)}</span>`;$('#toasts').append(node);setTimeout(()=>node.remove(),6000);}
function go(page){if(!titles[page])return;model.page=page;model.query='';model.tab='general';render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);}
function setEditor(kind,item=null,action='update',type=0){
  model.editor={kind,action,item:item?structuredClone(item):null,values:kind==='role'?{name:item?.name??'',color:item?.color??0,hoist:item?.hoist??false,mentionable:item?.mentionable??false}:{name:item?.name??'',type:item?.type??type,parent_id:item?.parent_id??null,topic:item?.topic??'',rate_limit_per_user:item?.rate_limit_per_user??0,user_limit:item?.user_limit??0},permissionChanges:{},overwriteChanges:{},approval:null};
  model.reviewSignature=null;model.awaitingEdit=false;model.tab='general';model.overwriteRole='';
}
function ensureEditor(kind){const inv=inventory();if(!inv)return;if(model.editor?.kind!==kind){const list=kind==='role'?inv.roles:inv.channels;setEditor(kind,list?.find(x=>!x.readOnlyReason)??list?.[0]??null,list?.length?'update':'create');}}
function editorRequest(){const e=model.editor;if(!e)return null;const req={kind:e.kind,action:e.action,values:{}};if(e.item){req.id=e.item.id;req.revision=e.item.revision;}
  if(e.kind==='role'){req.values={name:e.values.name.trim(),color:Number(e.values.color),hoist:!!e.values.hoist,mentionable:!!e.values.mentionable};req.permissionChanges={...e.permissionChanges};}
  else {const t=Number(e.values.type);req.values={name:e.values.name.trim(),parent_id:t===4?null:e.values.parent_id||null};if(e.action==='create')req.values.type=t;if(t===0){req.values.topic=e.values.topic;req.values.rate_limit_per_user=Number(e.values.rate_limit_per_user);}if(t===2)req.values.user_limit=Number(e.values.user_limit);req.overwriteChanges=Object.entries(e.overwriteChanges).map(([roleId,permissions])=>({roleId,permissions}));}
  return req;
}
function invalidate(){if(model.editor)model.editor.approval=null;model.reviewSignature=null;model.awaitingEdit=false;const button=$('#applyEdit');if(button)button.disabled=true;const label=$('#draftStatus');if(label)label.textContent=model.state.demo?'وضع العرض · الحفظ الحقيقي معطّل':'مسودة محلية · راجع التعديل قبل الحفظ';const box=$('#editReview');if(box)box.remove();}

async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:{'X-Cortex-Key':apiKey,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});let data;try{data=await response.json();}catch{throw new Error('تعذّر قراءة استجابة الخدمة المحلية.');}if(!response.ok)throw new Error(data.error??data.message??'تعذّرت العملية المحلية.');return data;}
async function action(name,extra={}){
  if(busy())return;if(!['stop','shutdown','client-closed'].includes(name)&&!model.state.demo&&(!(model.config.token||model.state.hasCredentials)||!/^\d{16,22}$/.test(guildId()))){toast('أدخل توكن البوت ورقم السيرفر أولًا.');go('settings');return;}
  model.requestEpoch=(model.requestEpoch??0)+1;model.postInFlight=true;model.pending=true;model.runningAction=name;model.state.error=null;model.localError=null;render();
  try{await api('/api/action',{action:name,config:{...(model.config.token?{token:model.config.token}:{}),guildId:guildId(),...extra}});model.postInFlight=false;model.credentialsDirty=false;await pollState(true);}
  catch(error){model.postInFlight=false;model.pending=false;model.runningAction=null;model.localError=error.message;toast(error.message,'error');render();}
}
async function pollState(force=false){if(polling||model.postInFlight)return;polling=true;const epoch=model.requestEpoch??0;try{
  const data=await api('/api/state');if(epoch!==(model.requestEpoch??0)||model.postInFlight)return;const previous=model.state;model.state=data;model.pending=false;model.connectionError=false;
  const inv=inventory();if(!model.config.guildId&&inv?.guildId)model.config.guildId=String(inv.guildId);
  const rawInventory=data.inventory??data.diagnostics?.inventory;
  const invSignature=rawInventory?JSON.stringify(rawInventory):'';
  const reportSignature=(data.reports?.files??[]).map(file=>file.name+':'+file.size).join('|');if(!data.busy){if(model.loaded&&model.lastReports!==undefined&&model.lastReports!==reportSignature&&reportSignature)toast('توجد تقارير جديدة جاهزة للتنزيل في سجل النشاط.','success');model.lastReports=reportSignature;}
  let refresh=force||!model.loaded||previous.busy!==data.busy||model.lastInventory!==invSignature||previous.error!==data.error;
  if(model.lastInventory&&model.lastInventory!==invSignature&&model.editor?.item){const fresh=(model.editor.kind==='role'?inv?.roles:inv?.channels)?.find(x=>x.id===model.editor.item.id);if(fresh&&fresh.revision!==model.editor.item.revision){const kind=model.editor.kind;setEditor(kind,fresh);toast('تم تحديث العنصر من السيرفر. راجع القيم الحالية.');}else if(!fresh){model.editor=null;}}
  model.lastInventory=invSignature;
  if(model.awaitingEdit&&!data.busy&&data.editPreview){const signature=JSON.stringify(editorRequest());if(signature===model.reviewSignature){model.editor.approval=data.editPreview;model.lastEditHash=data.editPreview.approvalHash;model.awaitingEdit=false;refresh=true;}}
  if(model.awaitingEdit&&!data.busy&&data.error){model.awaitingEdit=false;refresh=true;}
  const stateSignature=JSON.stringify([data.preview?.approvalHash,data.preview?.summary,data.editPreview?.approvalHash,data.operation]);if(model.lastStateSignature!==stateSignature){refresh=true;model.lastStateSignature=stateSignature;}
  if(!model.loaded||!previous.error&&data.error) {if(data.error)toast(typeof data.error==='string'?data.error:data.error.message??'تعذّرت العملية.','error');}
  if(!data.busy&&(previous.busy||model.runningAction)){const op=model.runningAction??(typeof previous.operation==='string'?previous.operation:previous.operation?.action);model.runningAction=null;if(!data.error){if(op==='edit-apply'){model.editor=null;toast('تم حفظ التعديل. جارٍ تحديث بيانات السيرفر.','success');setTimeout(()=>action('inventory'),80);}else if(op==='check'||op==='inventory')toast(model.state.demo?'تم تحديث بيانات العرض التوضيحي.':'تم تحديث بيانات السيرفر بنجاح.','success');}}
  model.loaded=true;updateChrome();if(refresh)render();else if(model.page==='logs')renderLogsOnly();
 }catch(error){model.pending=false;if(!model.connectionError){model.connectionError=true;$('#footerStatus').textContent='الخدمة المحلية غير متصلة';if(!model.loaded){model.loaded=true;render();toast('تعذّر الاتصال بالخدمة المحلية. افتح CortexManager.exe مجددًا.','error');}}}finally{polling=false;}}

function updateChrome(){
  $('#sidebarGuildName').textContent=guildName();$('#sidebarGuildId').textContent=guildId()||'اربط البوت للبدء';
  const inv=inventory();$('#channelCountNav').textContent=inv?.channels.filter(c=>c.type!==4).length??'—';$('#roleCountNav').textContent=inv?.roles.length??'—';$('#demoBadge').classList.toggle('hidden',!model.state.demo);
  const pill=$('#connectionPill');pill.classList.toggle('online',online());$('b',pill).textContent=online()?'البوت متصل Online':model.state.demo?'بيانات توضيحية':'البوت غير متصل';
  $('#refreshButton').disabled=busy();$('#footerStatus').textContent=busy()?'جارٍ تنفيذ العملية…':model.state.error?'تحتاج العملية إلى المراجعة':inv?'آخر تحديث '+shortTime(inv.capturedAt):'جاهز للاتصال بالسيرفر';
  let bar=$('.loading-bar');if(busy()&&!bar){bar=document.createElement('div');bar.className='loading-bar';document.body.append(bar);}if(!busy()&&bar)bar.remove();
}
function heading(title,description,eyebrow,actions=''){return `<div class="page-heading"><div><div class="page-eyebrow">${esc(eyebrow)}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function button(label,id,style='btn-ghost',name='',disabled=false){return `<button class="btn ${style}" id="${id}" ${disabled?'disabled':''}>${name?icon(name):''}<span>${esc(label)}</span></button>`;}
function panelTitle(title,subtitle,name,link=''){return `<div class="panel-header"><div class="panel-title"><span>${icon(name)}</span><div><h2>${title}</h2>${subtitle?`<small>${subtitle}</small>`:''}</div></div>${link}</div>`;}
function noInventory(kind='server'){return `<section class="panel empty-state"><div class="empty-illustration">${icon(kind==='roles'?'shield':kind==='channels'?'hash':'link')}</div><h2>سيرفرك… في مكان واحد</h2><p>اربط البوت بسيرفرك لعرض الأقسام والقنوات والرتب الحالية، ثم عدّل كل عنصر بمعاينة واضحة قبل الحفظ.</p>${button('إعداد الاتصال','emptyConnect','btn-primary','link')}</section>`;}
function bindEmpty(){const b=$('#emptyConnect');if(b)b.onclick=()=>go('settings');}

function render(){updateChrome();$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===model.page));$('#pageCrumb').textContent=titles[model.page];const renderers={overview:renderOverview,channels:()=>renderEntities('channel'),roles:()=>renderEntities('role'),redesign:renderRedesign,permissions:renderPermissions,logs:renderLogs,settings:renderSettings};renderers[model.page]();if(model.page==='permissions')addInviteTools();if(model.page==='redesign'&&model.state.demo)showDemoDesignNote();$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));bindEmpty();}

function renderOverview(){const inv=inventory(),channels=inv?.channels??[],roles=inv?.roles??[];const cats=channels.filter(c=>c.type===4),text=channels.filter(c=>c.type===0),voice=channels.filter(c=>c.type===2),protectedRoles=roles.filter(r=>/OWNER/.test(r.name));
  $('#main').innerHTML=heading('كل تفاصيل مجتمعك، بوضوح <span class="emoji">✨</span>','مرحبًا بك في مساحة إدارة سيرفرك. نظّم، عدّل، وابنِ مجتمعك بثقة.','YOUR COMMUNITY, YOUR WAY',button(inv?'تحديث السيرفر':'ربط السيرفر','overviewRefresh','btn-ghost',inv?'refresh':'link',busy()))+
  `<section class="hero"><div class="hero-copy"><div class="hero-kicker"><span></span>${inv?'مساحة مجتمعك جاهزة للإدارة':'واجهة جديدة. تجربة أجمل.'}</div><h2>${inv?'أهلًا بك في '+esc(guildName()):'سيرفر استثنائي يبدأ من هنا'} <span class="emoji">🎮</span></h2><p>${inv?'قنواتك ورتبك الحالية أمامك. خصّص كل تفصيلة، راجع التغييرات، واجعل تجربة مجتمعك أفضل.':'لوحة احترافية لإدارة قنواتك، ترتيب رتبك، وتشغيل بوتك. كل شيء واضح، من المعاينة حتى التأكيد.'}</p><div class="hero-bottom">${button(inv?'استكشف قنوات السيرفر':'ابدأ ربط السيرفر','heroChannels','btn-primary',inv?'hash':'link')}<span class="hero-caption">${icon('shield')} حماية القيادة مفعّلة دائمًا</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="art-center">${icon('spark')}</div><span class="art-bubble emoji">🎮</span><span class="art-bubble emoji">🎙️</span><span class="art-bubble emoji">👑</span><span class="art-star s1">✦</span><span class="art-star s2">✦</span><span class="art-star s3">✧</span></div></section>`+
  `<div class="stats-grid">${stat('القنوات النصية',inv?text.length:'—','hash',`${cats.length} أقسام منظمة`,'جاهزة للمحادثات')}${stat('القنوات الصوتية',inv?voice.length:'—','voice','مساحات للعب والتواصل','تواصل بصوتك')}${stat('رتب المجتمع',inv?roles.length:'—','users',`${roles.filter(r=>r.readOnlyReason).length} رتب محفوظة`,'صلاحيات لكل دور')}${stat('حماية السيرفر',inv?'مفعّلة':'آمنة','shield','القيادة والتكاملات محفوظة','تأكيد قبل كل تعديل')}</div>`+
  `<div class="content-grid"><section class="panel">${panelTitle('مساحات مجتمعك','لمحة عن الأقسام والقنوات الموجودة','hash',`<button class="text-link" data-go="channels">عرض الكل ${icon('arrow')}</button>`)}<div class="panel-body">${inv?channelOverview(channels):`<div class="no-result">أضف بيانات الاتصال لعرض قنوات السيرفر الحقيقية.</div>`}<div class="preview-note">${icon('refresh')} ${model.state.demo?'بيانات توضيحية للتصميم؛ غير متصلة بسيرفرك':inv?'قنوات حقيقية من السيرفر المحدد':'لا تُعرض بيانات سيرفر قبل الاتصال'}${model.state.demo?' · لا اتصال بديسكورد':''}</div></div></section><div class="overview-right"><section class="panel">${panelTitle('رتب القيادة المحمية','صلاحياتها وترتيبها وتوزيعها محفوظ','shield')}<div class="panel-body">${(protectedRoles.length?protectedRoles.slice(0,2):[{name:'★ OWNER ★'},{name:'★ CO_OWNER ★'}]).map((r,i)=>`<div class="protected-role"><span class="role-crown ${i?'purple':''} emoji">${i?'💎':'👑'}</span><span class="protected-role-name ${i?'purple':''}"><strong>${esc(r.name)}</strong><small>${i?'إدارة مشتركة محمية':'قيادة السيرفر محفوظة'}</small></span><span class="protected-tag">${icon('lock')} محمية</span></div>`).join('')}</div></section><section class="panel">${panelTitle('حالة مساحة العمل','كل خطوة واضحة وتحت تحكمك','log',`<button class="text-link" data-go="logs">السجل ${icon('arrow')}</button>`)}<div class="panel-body">${activityOverview()}</div></section></div></div>`;
  $('#overviewRefresh').onclick=()=>inv?action('inventory'):go('settings');$('#heroChannels').onclick=()=>go(inv?'channels':'settings');
}
function stat(label,value,name,note,caption){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(name)}</span></div><div class="stat-value" ${typeof value==='string'&&value.length>2?'style="font-size:25px;letter-spacing:0"':''}>${value}</div><div class="stat-bottom">${icon('check')} ${note}<span>· ${caption}</span></div></article>`;}
function channelOverview(channels){const categories=channels.filter(c=>c.type===4).slice(0,2);return categories.map((c,index)=>`<div class="channel-preview-group"><div class="mini-category">${icon('chevron')} <span class="emoji">${esc(c.name)}</span></div>${channels.filter(x=>x.parent_id===c.id).slice(0,index?2:3).map((ch,i)=>`<div class="mini-channel ${!index&&!i?'selected':''}">${icon(typeIcon(ch.type))}<span class="emoji">${esc(ch.name)}</span>${ch.readOnlyReason?icon('lock'):!index&&!i?'<span class="channel-tag">قناة المجتمع</span>':''}</div>`).join('')}</div>`).join('')||channels.filter(c=>c.type!==4).slice(0,5).map(c=>`<div class="mini-channel">${icon(typeIcon(c.type))}<span class="emoji">${esc(c.name)}</span></div>`).join('')||'<div class="no-result">لا توجد قنوات في السيرفر.</div>';}
function activityOverview(){return `<div class="activity-line"><span class="activity-dot"></span><div><p>${inventory()?'تم تحميل بيانات السيرفر':'مساحة العمل جاهزة للاتصال'}</p><small>${model.state.demo?'بيانات توضيحية · دون اتصال بديسكورد':inventory()?'القنوات والرتب متاحة للعرض والتحرير':'أدخل التوكن ورقم السيرفر للبدء'}</small></div><time>${inventory()?shortTime(inventory().capturedAt):'الآن'}</time></div><div class="activity-line"><span class="activity-dot"></span><div><p>حماية القيادة والتكاملات مفعّلة</p><small>OWNER وCO_OWNER لا تتغيران</small></div>${icon('lock')}</div><div class="activity-line"><span class="activity-dot"></span><div><p>المعاينة تسبق التنفيذ دائمًا</p><small>أي تعديل يحتاج مراجعتك وتأكيدك</small></div>${icon('check')}</div>`;}

function renderEntities(kind){const inv=inventory(),isRole=kind==='role';$('#main').innerHTML=heading(isRole?'رتب تعكس هوية مجتمعك':'كل مساحة… لها مكانها <span class="emoji">💬</span>',isRole?'شاهد الرتب الحالية، خصّص ألوانها، واضبط الصلاحيات لكل دور.':'استعرض الأقسام والغرف الموجودة في السيرفر، وعدّلها بالطريقة التي تناسبك.',isRole?'ROLES & PERMISSIONS':'CHANNELS & CATEGORIES',button('تحديث','entityRefresh','btn-ghost','refresh',busy())+button(isRole?'إنشاء رتبة':'إضافة مساحة','addEntity','btn-primary','plus',busy()||!inv));if(!inv){$('#main').insertAdjacentHTML('beforeend',noInventory(isRole?'roles':'channels'));$('#entityRefresh').onclick=()=>action('inventory');return;}ensureEditor(kind);
  $('#main').insertAdjacentHTML('beforeend',`<div class="entity-layout"><section class="panel entity-browser"><div class="browser-toolbar"><div class="search-box">${icon('search')}<input id="entitySearch" type="search" value="${esc(model.query)}" placeholder="${isRole?'ابحث عن رتبة…':'ابحث عن قناة أو قسم…'}" aria-label="البحث في ${isRole?'الرتب':'القنوات'}"></div></div><div class="browser-meta"><span>${isRole?'رتب السيرفر':'هيكل السيرفر'}</span><span>${isRole?inv.roles.length+' رتبة':inv.channels.length+' عنصر'}</span></div><div class="browser-tree" id="entityTree">${entityTree(kind)}</div></section><section class="panel inspector" id="entityInspector">${inspector(kind)}</section></div>`);
  $('#entityRefresh').onclick=()=>action('inventory');$('#addEntity').onclick=()=>isRole?createEntity('role'):showCreateChannel();$('#entitySearch').oninput=event=>{model.query=event.target.value;$('#entityTree').innerHTML=entityTree(kind);bindTree(kind);};bindTree(kind);bindInspector();
}
function entityTree(kind){const inv=inventory(),query=model.query.toLocaleLowerCase('ar'),e=model.editor;const item=(entity,child=false)=>`<button class="tree-item ${child?'tree-child ':''}${e?.item?.id===entity.id?'active':''}" data-entity-id="${esc(entity.id)}" title="${esc(entity.name)}">${kind==='role'?`<span class="role-dot" style="background:${colorHex(entity.color)||'#8b95aa'}"></span>`:icon(typeIcon(entity.type))}<span class="label emoji">${esc(entity.name)}</span>${entity.readOnlyReason?icon('lock'):kind==='role'?'<span class="role-row-meta">قابلة للتعديل</span>':''}</button>`;
  if(kind==='role')return inv.roles.filter(r=>r.name.toLocaleLowerCase('ar').includes(query)).map(r=>item(r)).join('')||'<div class="no-result">لا توجد رتبة بهذا الاسم.</div>';
  if(query)return inv.channels.filter(c=>c.name.toLocaleLowerCase('ar').includes(query)).map(c=>item(c)).join('')||'<div class="no-result">لا توجد قناة بهذا الاسم.</div>';
  return inv.channels.filter(c=>c.type===4).map(c=>`<details class="tree-group" open><summary>${icon('chevron')}<span class="emoji">${esc(c.name)}</span><button class="category-select" type="button" data-entity-id="${esc(c.id)}" aria-label="تعديل القسم ${esc(c.name)}">${icon('settings')}</button></summary>${inv.channels.filter(ch=>ch.parent_id===c.id).map(ch=>item(ch,true)).join('')}</details>`).join('')+inv.channels.filter(c=>c.type!==4&&!inv.channels.some(parent=>parent.id===c.parent_id)).map(c=>item(c)).join('');
}
function bindTree(kind){$$('[data-entity-id]').forEach(b=>b.onclick=event=>{event.preventDefault();const list=kind==='role'?inventory().roles:inventory().channels;setEditor(kind,list.find(x=>x.id===b.dataset.entityId));render();});}
function inspector(kind){const e=model.editor;if(!e)return '<div class="empty-state"><h2>اختر عنصرًا من القائمة</h2></div>';const role=kind==='role',readOnly=e.item?.readOnlyReason;return `<div class="inspector-hero" ${role?`style="--entity-color:${colorHex(e.values.color)}30"`:''}><div class="entity-symbol ${role?'role-symbol':''}">${role?'<span class="emoji">🛡️</span>':icon(typeIcon(Number(e.values.type)))}</div><div class="entity-title"><strong class="emoji">${esc(e.values.name|| (role?'رتبة جديدة':'مساحة جديدة'))}</strong><small>${esc(role?'رتبة في السيرفر':typeLabel(Number(e.values.type)))} <code>${esc(e.item?.id??'NEW')}</code></small></div><span class="entity-status">${readOnly?'محمية · للعرض فقط':e.action==='create'?'مسودة جديدة':'إعدادات العنصر'}</span></div><div class="inspector-body">${(model.state.error||model.localError)&&!busy()?`<div class="notice yellow" role="alert"><div><strong>تعذّرت العملية؛ راجع السبب قبل المحاولة مجددًا</strong>${esc(model.state.error||model.localError)}<br><button class="btn btn-ghost btn-small" type="button" id="reloadEditor">تحديث بيانات السيرفر</button></div></div>`:''}${readOnly?`<div class="notice green">${icon('lock')}<div><strong>هذا العنصر محفوظ</strong>${esc(readOnly)}. صلاحياته وأعضاؤه وترتيبه تبقى محفوظة.</div></div>`:''}<div class="page-tabs"><button class="page-tab ${model.tab==='general'?'active':''}" data-editor-tab="general">${role?'تفاصيل الرتبة':'إعدادات القناة'}</button><button class="page-tab ${model.tab==='permissions'?'active':''}" data-editor-tab="permissions">${role?'صلاحيات الرتبة':'أذونات الوصول'}</button></div>${model.tab==='general'?(role?roleGeneral(e,readOnly):channelGeneral(e,readOnly)):(role?rolePermissions(e,readOnly):channelPermissions(e,readOnly))}${e.approval?`<div class="review-box" id="editReview"><h3>${icon('eye')} تمت معاينة التعديل</h3><div class="review-summary">${esc(e.approval.summary)}</div></div>`:''}</div><div class="inspector-footer"><span class="save-note">${icon(readOnly?'lock':'info')}<span id="draftStatus">${readOnly?'هذه البيانات للعرض فقط':model.state.demo?'وضع العرض · الحفظ الحقيقي معطّل':e.approval?'الخطة جاهزة. الحفظ يتطلب تأكيدك.':'مسودة محلية · راجع التعديل قبل الحفظ'}</span></span><div class="editor-actions">${button('معاينة التعديل','reviewEdit','btn-ghost','eye',busy()||!!readOnly)}${button('حفظ التغيير','applyEdit','btn-primary','check',busy()||!!readOnly||!e.approval||model.state.demo)}</div></div>`;}
function field(label,id,value,type='text',extra='',disabled=false,help=''){return `<div class="field ${extra}"><label for="${id}">${label}</label><input type="${type}" id="${id}" value="${esc(value)}" ${disabled?'disabled':''}>${id==='editName'?emojiPalette(disabled):''}${help?`<span class="field-help">${help}</span>`:''}</div>`;}
function emojiPalette(disabled){return `<div class="emoji-palette" aria-label="إضافة إيموجي للاسم"><span>إيموجي للاسم</span><div>${['🎮','💬','🛡️','📢','🎙️','👑','💎','☕','🌿','🎫','🏆','✨'].map(emoji=>`<button class="emoji" type="button" data-emoji="${emoji}" aria-label="إضافة ${emoji} للاسم" title="إضافة ${emoji}" ${disabled?'disabled':''}>${emoji}</button>`).join('')}</div><small>أو استخدم <kbd>Win + .</kbd></small></div>`;}
function channelGeneral(e,readOnly){const type=Number(e.values.type),disabled=readOnly||busy();return `<div class="form-grid">${field('اسم '+(type===4?'القسم':'القناة'),'editName',e.values.name,'text','full',disabled,'استخدم اسمًا واضحًا وإيموجي تعبّر عن المكان. الإيموجي تُعرض بألوانها الكاملة.')} ${type!==4?`<div class="field full"><label for="editParent">القسم الرئيسي</label><select id="editParent" ${disabled?'disabled':''}><option value="">بدون قسم</option>${inventory().channels.filter(c=>c.type===4).map(c=>`<option value="${esc(c.id)}" ${c.id===e.values.parent_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="field-help">نقل القناة يحافظ على أذوناتها الحالية.</span></div>`:''}${type===0?`<div class="field full"><label for="editTopic">وصف القناة <small>اختياري</small></label><textarea id="editTopic" maxlength="1024" ${disabled?'disabled':''} placeholder="ماذا يحدث في هذه المساحة؟">${esc(e.values.topic)}</textarea></div>${field('تهدئة الرسائل (ثانية)','editSlowmode',e.values.rate_limit_per_user,'number','',disabled,'0 لتعطيل وضع التهدئة. الحد الأقصى 21600.')}`:''}${type===2?field('الحد الأقصى للأعضاء','editUserLimit',e.values.user_limit,'number','',disabled,'0 يسمح بعدد غير محدود. الحد الأقصى 99.'):''}</div><div class="notice" style="margin-top:23px;margin-bottom:0">${icon('shield')}<div><strong>التعديل يبدأ بمعاينة</strong>لن يتغير أي شيء في السيرفر حتى تراجع التفاصيل وتؤكد الحفظ.</div></div>`;}
function roleGeneral(e,readOnly){const disabled=readOnly||busy();return `<div class="form-grid">${field('اسم الرتبة','editName',e.values.name,'text','full',disabled,'اسم مميز مع إيموجي يجعل أعضاء مجتمعك يتعرفون على دورهم بسرعة.')}<div class="field full"><label for="editColorHex">لون الرتبة</label><div class="color-field"><input id="editColor" type="color" value="${colorHex(e.values.color)}" ${disabled?'disabled':''} aria-label="اختيار لون الرتبة"><input id="editColorHex" type="text" value="${colorHex(e.values.color).toUpperCase()}" maxlength="7" ${disabled?'disabled':''} aria-label="لون الرتبة HEX"></div><span class="field-help">يظهر هذا اللون على أسماء الأعضاء في ديسكورد.</span></div></div><h3 class="section-label">${icon('users')} طريقة الظهور</h3><label class="toggle-row"><span class="toggle-copy"><strong>عرض الرتبة بشكل منفصل</strong><small>تجميع أعضائها في قائمة الأعضاء</small></span><input class="switch" type="checkbox" id="editHoist" ${e.values.hoist?'checked':''} ${disabled?'disabled':''}></label><label class="toggle-row"><span class="toggle-copy"><strong>السماح بمنشن الرتبة</strong><small>يمكن للجميع الإشارة إلى هذه الرتبة</small></span><input class="switch" type="checkbox" id="editMentionable" ${e.values.mentionable?'checked':''} ${disabled?'disabled':''}></label>`;}
function rolePermissions(e,readOnly){const flags=e.item?.flags??inventory().permissions.map(p=>({...p,granted:false,canGrant:p.granted}));return `<div class="notice">${icon('info')}<div>الصلاحيات تتطبق على جميع أعضاء الرتبة. يتم حفظ الصلاحيات الأخرى وتوزيع الأعضاء كما هما.</div></div><div class="permissions-grid">${flags.map(flag=>{const checked=e.permissionChanges[flag.name]??flag.granted;return `<label class="toggle-row"><span class="toggle-copy"><strong ${flag.name==='Administrator'?'class="permission-warn"':''}>${esc(permissionLabel(flag.name))}</strong><small>${esc(flag.name)}</small></span><input class="switch" type="checkbox" data-permission="${esc(flag.name)}" ${checked?'checked':''} ${readOnly||busy()||!flag.canGrant&&!flag.granted?'disabled':''} aria-label="${esc(permissionLabel(flag.name))}"></label>`;}).join('')}</div>`;}
function channelPermissions(e,readOnly){const roles=inventory().roles.filter(r=>!r.managed&&!/OWNER/.test(r.name)&&(!r.readOnlyReason||r.name==='@everyone'));if(!model.overwriteRole||!roles.some(r=>r.id===model.overwriteRole))model.overwriteRole=roles[0]?.id??'';const chosen=roles.find(r=>r.id===model.overwriteRole);const existing=e.item?.overwrites?.find(w=>w.type===0&&w.id===chosen?.id);return `<div class="notice">${icon('key')}<div>حدّد رتبة واضبط وصولها لهذه القناة. أذونات الأعضاء والقيادة والتكاملات تبقى محفوظة.</div></div><div class="field permission-role-select"><label for="overwriteRole">الرتبة المراد ضبط وصولها</label><select id="overwriteRole" ${busy()?'disabled':''}>${roles.map(r=>`<option value="${esc(r.id)}" ${r.id===model.overwriteRole?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div>${!roles.length?'<div class="no-result">لا توجد رتب متاحة للتحرير.</div>':`<div class="overwrite-permissions">${inventory().channelPermissionNames.map(name=>{const value=e.overwriteChanges[chosen.id]?.[name]??existing?.flags.find(f=>f.name===name)?.state??'inherit';return `<label class="overwrite-row"><span>${esc(permissionLabel(name))}</span><select data-overwrite="${esc(name)}" ${readOnly||busy()?'disabled':''} aria-label="${esc(permissionLabel(name))}"><option value="inherit" ${value==='inherit'?'selected':''}>وراثة</option><option value="allow" ${value==='allow'?'selected':''}>سماح ✓</option><option value="deny" ${value==='deny'?'selected':''}>منع ×</option></select></label>`;}).join('')}</div>`}`;}
function bindInspector(){const e=model.editor;if(!e)return;const reload=$('#reloadEditor');if(reload)reload.onclick=()=>action('inventory');$$('[data-editor-tab]').forEach(b=>b.onclick=()=>{model.tab=b.dataset.editorTab;render();});const binds={editName:'name',editTopic:'topic',editParent:'parent_id',editSlowmode:'rate_limit_per_user',editUserLimit:'user_limit'};for(const [id,prop]of Object.entries(binds)){const input=$('#'+id);if(input)input.oninput=()=>{e.values[prop]=input.value;invalidate();};}
  $$('[data-emoji]').forEach(button=>button.onclick=()=>{const input=$('#editName');let name=input.value;if(e.palettePrefix&&name.startsWith(e.palettePrefix))name=name.slice(e.palettePrefix.length);e.palettePrefix=button.dataset.emoji+'・';e.values.name=e.palettePrefix+name;input.value=e.values.name;invalidate();input.focus();input.setSelectionRange(input.value.length,input.value.length);});
  for(const [id,prop]of [['editHoist','hoist'],['editMentionable','mentionable']]){const input=$('#'+id);if(input)input.onchange=()=>{e.values[prop]=input.checked;invalidate();};}
  const c=$('#editColor'),hex=$('#editColorHex');if(c)c.oninput=()=>{e.values.color=parseInt(c.value.slice(1),16);hex.value=c.value.toUpperCase();invalidate();};if(hex)hex.oninput=()=>{invalidate();if(/^#[0-9a-f]{6}$/i.test(hex.value)){e.values.color=parseInt(hex.value.slice(1),16);c.value=hex.value;invalidate();}};
  $$('[data-permission]').forEach(input=>input.onchange=()=>{e.permissionChanges[input.dataset.permission]=input.checked;invalidate();});const selector=$('#overwriteRole');if(selector)selector.onchange=()=>{model.overwriteRole=selector.value;render();};$$('[data-overwrite]').forEach(input=>input.onchange=()=>{e.overwriteChanges[model.overwriteRole]??={};e.overwriteChanges[model.overwriteRole][input.dataset.overwrite]=input.value;invalidate();});
  $('#reviewEdit').onclick=()=>{if(!validateEditor())return;if(!e.values.name.trim()){toast('أدخل اسم العنصر أولًا.');$('#editName')?.focus();return;}model.reviewSignature=JSON.stringify(editorRequest());model.awaitingEdit=true;action('edit-preview',{editRequest:editorRequest()});};$('#applyEdit').onclick=showApplyDialog;
}
function createEntity(kind,type=0){setEditor(kind,null,'create',type);model.page=kind==='role'?'roles':'channels';render();setTimeout(()=>$('#editName')?.focus(),0);}
function showCreateChannel(){showDialog(`<div class="dialog-symbol">${icon('plus')}</div><h2>أضف مساحة لمجتمعك</h2><p>اختر نوع المساحة. ستراجع إعداداتها قبل إنشائها في السيرفر.</p><div class="field"><label for="newChannelType">نوع المساحة</label><select id="newChannelType"><option value="0">💬 قناة نصية</option><option value="2">🎙️ قناة صوتية</option><option value="4">📁 قسم للقنوات</option></select></div><div class="dialog-actions"><button class="btn btn-ghost" value="cancel">إلغاء</button><button class="btn btn-primary" type="button" id="createChosen">متابعة ${icon('arrow')}</button></div>`);$('#createChosen').onclick=()=>{const type=Number($('#newChannelType').value);$('#confirmDialog').close();createEntity('channel',type);};}
function showApplyDialog(){const approval=model.editor?.approval;if(!approval||model.state.demo)return;showDialog(`<div class="dialog-symbol">${icon('check')}</div><h2>تأكيد حفظ التعديل</h2><p>سيُحفظ هذا التغيير في <strong>${esc(guildName())}</strong>. راجع التفاصيل قبل المتابعة.</p><div class="review-summary">${esc(approval.summary)}</div><div class="dialog-actions"><button class="btn btn-ghost" value="cancel">العودة للمراجعة</button><button class="btn btn-primary" type="button" id="confirmApply">${icon('check')} تأكيد وحفظ</button></div>`);$('#confirmApply').onclick=()=>{$('#confirmDialog').close();const confirmation={confirmed:true,guildId:guildId(),approvalHash:approval.approvalHash};model.editor.approval=null;action('edit-apply',{editConfirmation:confirmation});};}
function showDialog(content){const dialog=$('#confirmDialog');$('#dialogContent').innerHTML=content;if(dialog.open)dialog.close();dialog.showModal();}

function renderSettings(){const state=model.state;$('#main').innerHTML=heading('اتصال واضح. تحكّم كامل.','اربط بوت ديسكورد بالسيرفر الذي تريد إدارته. صلاحياته تأتي من إعدادات ديسكورد.','CONNECTION & BOT SETTINGS')+`<section class="panel settings-panel"><div class="settings-heading"><div class="entity-symbol">${icon('link')}</div><div><h2>إعداد الاتصال بالسيرفر</h2><p>التوكن يبقى في ذاكرة التطبيق أثناء تشغيله.</p></div></div><div class="settings-body">${state.demo?`<div class="notice yellow">${icon('info')}<div><strong>هذه معاينة توضيحية للواجهة</strong>لا يوجد اتصال بديسكورد، ولا تُنفّذ عمليات على أي سيرفر.</div></div>`:''}<div class="field"><label for="botToken">توكن البوت <small>Bot Token</small></label><div class="input-with-action"><input id="botToken" class="ltr" type="password" autocomplete="off" spellcheck="false" placeholder="${state.hasCredentials?'التوكن متاح في ذاكرة الجلسة الحالية':'أدخل توكن البوت من Discord Developer Portal'}" value="${esc(model.config.token)}" ${busy()||online()?'disabled':''}><button id="revealToken" type="button" aria-label="إظهار أو إخفاء التوكن">${icon('eye')}</button></div><span class="field-help">لا تشارك التوكن مع أي شخص. لا يُحفظ في التخزين المحلي للمتصفح.</span></div>${field('رقم السيرفر <small>Server ID</small>','guildId',model.config.guildId,'text','',busy(),'لتغييره: انسخ رقم السيرفر من ديسكورد بعد تفعيل وضع المطوّر.')}<div class="settings-action-row">${button('تحميل السيرفر','connectCheck','btn-primary','link',busy())}${button(online()?'إيقاف البوت':'تشغيل البوت Online','toggleOnline',online()?'btn-ghost':'btn-success',online()?'stop':'play',busy())}<span class="inline-status">${busy()?'<span class="spinner"></span> جارٍ العمل…':online()?'● البوت متصل':'جاهز للاتصال'}</span></div><div class="settings-info"><div><strong>${icon('lock')} اتصال محلي</strong>بياناتك لا تمر بخادم خارجي للتطبيق.</div><div><strong>${icon('shield')} حماية ثابتة</strong>رتب القيادة والتكاملات محفوظة.</div><div><strong>${icon('eye')} مراجعة قبل التنفيذ</strong>التحميل والفحص لا يغيّران السيرفر.</div></div></div></section>`;
  $('#botToken').oninput=e=>{model.config.token=e.target.value.trim();model.credentialsDirty=true;model.editor=null;model.state.preview=null;model.state.editPreview=null;model.rebuildRead=false;};$('#guildId').classList.add('ltr');$('#guildId').maxLength=22;$('#guildId').oninput=e=>{const value=e.target.value.replace(/\D/g,'');e.target.value=value;if(model.config.guildId!==value){model.config.guildId=value;model.editor=null;model.state.preview=null;model.state.editPreview=null;model.rebuildRead=false;}};$('#revealToken').onclick=()=>{const input=$('#botToken');input.type=input.type==='password'?'text':'password';};$('#connectCheck').onclick=()=>action('check');$('#toggleOnline').onclick=()=>action(online()?'stop':'online');
}
function renderPermissions(){const inv=inventory(),diag=model.state.diagnostics;$('#main').innerHTML=heading('صلاحيات البوت، أمامك بوضوح','اعرف ما يستطيع البوت إدارته، وما يحتاج تعديلًا من إعدادات السيرفر.','BOT PERMISSION CHECK',button('فحص الآن','checkPermissions','btn-primary','key',busy()));$('#checkPermissions').onclick=()=>action('check');if(!inv){$('#main').insertAdjacentHTML('beforeend',noInventory());return;}const permissions=diag?.permissions??inv.permissions;$('#main').insertAdjacentHTML('beforeend',`<div class="notice green">${icon('shield')}<div><strong>${esc(diag?.botName??'البوت')} · متصل ببيانات ${esc(guildName())}</strong>تُقرأ الصلاحيات من ديسكورد. رفع رتبة البوت أو تعديل صلاحياته يتم من إعدادات السيرفر.</div></div><section class="panel">${panelTitle('صلاحيات الوصول والإدارة',`${permissions.filter(p=>p.granted).length} صلاحية متاحة من أصل ${permissions.length}`,'key')}<div class="panel-body permission-columns">${permissions.map(p=>`<div class="permission-row"><div><span>${esc(permissionLabel(p.name))}</span><br><code>${esc(p.name)}</code></div><span class="pill ${p.granted?'':'red'}">${icon(p.granted?'check':'close')} ${p.granted?'متاحة':'غير ممنوحة'}</span></div>`).join('')}</div></section>${diag?.inaccessibleChannels?.length?`<div class="notice yellow" style="margin-top:20px">${icon('lock')}<div><strong>قنوات لا يستطيع البوت إدارتها</strong>${diag.inaccessibleChannels.map(c=>esc(c.name)).join('، ')}</div></div>`:''}`);}

function renderRedesign(){const preview=model.state.preview;$('#main').innerHTML=heading('امنح مجتمعك بداية أجمل <span class="emoji">🚀</span>','تصميم ألعاب عربي منظّم، مع مراجعة كاملة لكل ما سيُنشأ وما سيُحفظ وما سيُزال.','SERVER REDESIGN STUDIO')+`<div class="redesign-grid"><section class="panel">${panelTitle('مسار إعادة التصميم','ثلاث خطوات واضحة، وتأكيد قبل أي حذف','spark')}<div class="panel-body"><div class="workflow-step ${inventory()?'complete':''}"><span class="step-number">${inventory()?icon('check'):'01'}</span><div><h3>ابدأ من السيرفر الحالي</h3><p>حمّل القنوات والرتب وافحص صلاحيات البوت قبل إنشاء أي خطة.</p>${button('تحديث بيانات السيرفر','designCheck','btn-ghost btn-small','refresh',busy())}</div></div><div class="workflow-step ${preview?'complete':''}"><span class="step-number">${preview?icon('check'):'02'}</span><div><h3>أنشئ الخطة وراجع التفاصيل</h3><p>معاينة منفصلة تعرض الإنشاء والتحديث والحذف، مع الرتب والقنوات المحفوظة وتوزيع الأعضاء.</p>${button('إنشاء معاينة كاملة','designPreview','btn-primary btn-small','eye',busy())}</div></div><div class="workflow-step"><span class="step-number">03</span><div><h3>نفّذ بعد موافقتك الصريحة</h3><p>يُنشأ الجديد أولًا. لا يبدأ حذف القديم إلا بعد التحقق من الخطة وتأكيد رقم السيرفر وعبارة الحذف.</p>${button('مراجعة تأكيد التنفيذ','designRebuild','btn-danger btn-small','shield',busy()||!preview?.ready||model.state.demo||!model.rebuildRead)}</div></div></div></section><section class="panel">${panelTitle('تصميم احترافي. أساس آمن.','قواعد ثابتة ترافق كل خطة','shield')}<div class="panel-body"><ul class="safety-list"><li>${icon('check')}<span>★ OWNER ★ و★ CO_OWNER ★ محفوظتان بالصلاحيات والترتيب والأعضاء.</span></li><li>${icon('check')}<span>@everyone ورتب البوتات والتكاملات لا تُحذف.</span></li><li>${icon('check')}<span>قنوات Community المحمية مثل rules وmoderator-only محفوظة.</span></li><li>${icon('check')}<span>الرتب الموزعة تُحفظ عندما لا يوجد نقل آمن لتوزيعها.</span></li><li>${icon('check')}<span>لا طرد، لا حظر، ولا حذف للسيرفر.</span></li><li>${icon('check')}<span>تنفيذ تدريجي يحترم حدود Discord API ويمنع التكرار.</span></li></ul><div class="notice" style="margin-top:22px;margin-bottom:0">${icon('info')}<div>الخطة تُبنى على حالة السيرفر الحالية. أي تغيّر مؤثر يستلزم معاينة جديدة.</div></div></div></section></div>${preview?`<section class="panel report-panel">${panelTitle('تقرير الخطة المقترحة','راجع جميع التفاصيل قبل إتاحة زر التنفيذ','eye',button('تنزيل التقرير','downloadPreview','btn-ghost btn-small','log'))}<div class="report-content">${formatReport(preview.summary??preview.report??'تم إنشاء الخطة. افتح التقرير لمراجعة التفاصيل.')}</div><div class="panel-body"><div class="rebuild-approved"><label><input type="checkbox" id="reviewedPlan" ${model.rebuildRead?'checked':''}><span>راجعت تقرير الإنشاء والحذف والرتب المحفوظة، وأرغب في فتح خطوة التأكيد الإضافي.</span></label></div></div></section>`:''}`;
  $('#designCheck').onclick=()=>action('inventory');$('#designPreview').onclick=()=>{model.rebuildRead=false;action('preview');};$('#designRebuild').onclick=showRebuildDialog;const reviewed=$('#reviewedPlan');if(reviewed)reviewed.onchange=()=>{model.rebuildRead=reviewed.checked;$('#designRebuild').disabled=busy()||!preview?.ready||model.state.demo||!model.rebuildRead;};const download=$('#downloadPreview');if(download)download.onclick=()=>downloadText(preview.summary??'',`cortex-preview-${guildId()}.txt`);
}
function formatReport(text){return String(text).split(/\r?\n/).map(raw=>{const line=raw.trim();if(!line)return '';if(line.startsWith('### '))return '<h3>'+esc(line.slice(4))+'</h3>';if(line.startsWith('## '))return '<h2>'+esc(line.slice(3))+'</h2>';if(line.startsWith('# '))return '<h2>'+esc(line.slice(2))+'</h2>';const safe=esc(line.replace(/^[-*] /,'')).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\b(CREATE|UPDATE|PRESERVE|DELETE|REUSE|KEEP)\b/g,(all)=>`<span class="report-action ${all==='DELETE'?'delete':['PRESERVE','KEEP'].includes(all)?'preserve':''}">${all}</span>`);return `<p>${safe}</p>`;}).join('');}
function downloadText(text,filename){const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function showRebuildDialog(){if(!model.state.preview?.ready||model.state.demo||!model.rebuildRead)return;showDialog(`<div class="dialog-symbol danger">${icon('shield')}</div><h2>تأكيد إعادة بناء السيرفر</h2><p>ستُنشأ عناصر التصميم الجديد أولًا، ثم تُزال العناصر القديمة المسموح بحذفها حسب الخطة. قد يُفقد محتوى القنوات المحذوفة. لا تنفّذ إلا بعد مراجعة التقرير.</p><div class="notice yellow">${icon('info')}<div><strong>${esc(guildName())}</strong>رقم السيرفر: <code>${esc(guildId())}</code></div></div><div class="field"><label for="confirmGuildId">اكتب رقم السيرفر المحدد للتأكيد</label><input class="ltr" id="confirmGuildId" type="text" autocomplete="off" placeholder="رقم السيرفر" spellcheck="false"></div><div class="field"><label for="confirmDelete">اكتب العبارة التالية كما هي<br><code>DELETE_ALL_OLD_CHANNELS_AND_ROLES</code></label><input class="ltr" id="confirmDelete" type="text" autocomplete="off" spellcheck="false" placeholder="عبارة التأكيد"></div><div class="dialog-actions"><button class="btn btn-ghost" value="cancel">إلغاء</button><button class="btn btn-danger" type="button" id="confirmRebuild" disabled>${icon('shield')} تأكيد وبدء التنفيذ</button></div>`);const validate=()=>$('#confirmRebuild').disabled=$('#confirmGuildId').value!==guildId()||$('#confirmDelete').value!=='DELETE_ALL_OLD_CHANNELS_AND_ROLES';$('#confirmGuildId').oninput=validate;$('#confirmDelete').oninput=validate;$('#confirmRebuild').onclick=()=>{const config={confirmGuildId:$('#confirmGuildId').value,confirmDelete:$('#confirmDelete').value};$('#confirmDialog').close();model.rebuildRead=false;action('rebuild',config);};}

function officialInvite(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='discord.com'&&u.pathname==='/oauth2/authorize'&&u.searchParams.get('guild_id')===guildId()?u.href:null;}catch{return null;}}
function addInviteTools(){const diag=model.state.diagnostics;if(!inventory()||!diag)return;const normal=officialInvite(diag.inviteURL),admin=officialInvite(diag.adminInviteURL);if(!normal&&!admin)return;$('.notice.green')?.insertAdjacentHTML('afterend',`<div class="invite-tools"><span>تحتاج منح صلاحيات البوت؟</span>${normal?button('فتح دعوة الصلاحيات المطلوبة','openInvite','btn-ghost','link'):''}${admin?button('دعوة Administrator…','adminInvite','btn-ghost','shield'):''}</div>`);const normalButton=$('#openInvite');if(normalButton)normalButton.onclick=()=>window.open(normal,'_blank','noopener,noreferrer');const adminButton=$('#adminInvite');if(adminButton)adminButton.onclick=()=>{showDialog(`<div class="dialog-symbol">${icon('shield')}</div><h2>دعوة بصلاحية Administrator</h2><p>تمنح هذه الدعوة البوت صلاحية إدارة كاملة في السيرفر. استخدمها فقط إذا كنت تريد ذلك. يمكنك منح الصلاحيات المطلوبة من الدعوة العادية.</p><div class="notice"><div><strong>${esc(guildName())}</strong>سيفتح رابط ديسكورد الرسمي؛ راجع صفحة الموافقة هناك.</div></div><div class="dialog-actions"><button class="btn btn-ghost" value="cancel">إلغاء</button><button class="btn btn-primary" type="button" id="confirmAdminInvite">فتح الدعوة الرسمية ${icon('link')}</button></div>`);$('#confirmAdminInvite').onclick=()=>{$('#confirmDialog').close();window.open(admin,'_blank','noopener,noreferrer');};};}
function showDemoDesignNote(){$('.page-heading')?.insertAdjacentHTML('afterend',`<div class="notice yellow">${icon('eye')}<div><strong>استكشف التصميم بأمان</strong>هذه بيانات توضيحية فقط. يمكنك إنشاء معاينة ورؤية التقارير؛ الحفظ وإعادة البناء الحقيقيان معطّلان.</div></div>`);}
function renderLogs(){$('#main').innerHTML=heading('كل خطوة لها سجل','تابع عمليات الاتصال والفحص والمراجعة والتنفيذ من مكان واحد.','ACTIVITY & OPERATION LOG',button('تنزيل السجل','downloadLogs','btn-ghost','log'))+`<section class="panel">${panelTitle('سجل مساحة العمل','سجل محلي لعمليات هذه الجلسة','log')}<div class="log-list" id="logList">${logsMarkup()}</div></section>`;$('#downloadLogs').onclick=()=>downloadText((model.state.logs??[]).map(l=>`${l.time??l.at??''} [${l.level??'info'}] ${l.message}`).join('\n'),'cortex-session-log.txt');renderReportFiles();}
const reportLabels={'edit-conflict.json':'سبب تعارض الحفظ مع المعاينة','preview.md':'تقرير معاينة إعادة البناء','plan.json':'خطة الإنشاء والحذف الكاملة','approval.json':'بيانات اعتماد الخطة','snapshot.json':'نسخة حالة السيرفر قبل التنفيذ','result.json':'نتيجة إعادة البناء','execution-log.txt':'سجل خطوات التنفيذ','failure.json':'تفاصيل العملية غير المكتملة','edit-preview.txt':'تقرير مراجعة التعديل','edit-plan.json':'خطة التعديل الكاملة','edit-snapshot.json':'حالة السيرفر قبل التعديل','edit-result.json':'نتيجة حفظ التعديل'};
function renderReportFiles(){let panel=$('#reportFilesPanel');if(!panel){$('#main').insertAdjacentHTML('beforeend',`<section class="panel report-panel" id="reportFilesPanel">${panelTitle('ملفات التقارير والنسخ المحلية','تنزيل التفاصيل الكاملة للخطط والعمليات في هذه الجلسة','folder')}<div class="panel-body" id="reportFiles"></div></section>`);panel=$('#reportFilesPanel');}const files=(model.state.reports?.files??[]).filter(file=>Object.hasOwn(reportLabels,file.name));$('#reportFiles').innerHTML=files.length?`<div class="report-files">${files.map(file=>`<button class="report-file" data-report="${esc(file.name)}">${icon('log')}<span><strong>${esc(reportLabels[file.name])}</strong><small>${esc(file.name)} · ${Number(file.size)<1024?Number(file.size)+' B':Math.ceil(Number(file.size)/1024)+' KB'}</small></span><b>تنزيل ${icon('arrow')}</b></button>`).join('')}</div>`:'<div class="no-result">ستظهر هنا ملفات المعاينة ونتائج التنفيذ عندما تُنشأ.</div>';$$('[data-report]',panel).forEach(button=>button.onclick=()=>downloadReport(button.dataset.report));}
async function downloadReport(name){if(!Object.hasOwn(reportLabels,name))return;try{const response=await fetch('/api/report/'+encodeURIComponent(name),{headers:{'X-Cortex-Key':apiKey},cache:'no-store'});if(!response.ok)throw new Error('تعذّر تنزيل التقرير. قد لا يكون متاحًا في هذه الجلسة.');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='cortex-'+name;link.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}catch(error){toast(error.message,'error');}}
function validateEditor(){const e=model.editor;if(!e)return false;if(e.values.name.trim().length>100){toast('الاسم يجب ألا يتجاوز 100 حرف.','error');$('#editName')?.focus();return false;}const hex=$('#editColorHex');if(hex&&!/^#[0-9a-f]{6}$/i.test(hex.value)){toast('أدخل لونًا صحيحًا مثل #9888FF.','error');hex.focus();return false;}const limits={rate_limit_per_user:[0,21600],user_limit:[0,99]};for(const [key,[min,max]]of Object.entries(limits)){if(key in e.values&&(!Number.isInteger(Number(e.values[key]))||Number(e.values[key])<min||Number(e.values[key])>max)){toast(key==='user_limit'?'حد الأعضاء يجب أن يكون بين 0 و99.':'التهدئة يجب أن تكون بين 0 و21600 ثانية.','error');return false;}}return true;}
function logsMarkup(){const logs=model.state.logs??[];return logs.length?[...logs].reverse().map(l=>`<div class="log-entry ${l.level==='error'?'error':''}">${icon(l.level==='error'?'info':'check')}<div class="log-message">${esc(typeof l.message==='string'?l.message:'تم تحديث حالة العملية.')}</div><time>${shortTime(l.time??l.at)}</time></div>`).join(''):'<div class="empty-state"><div class="empty-illustration">'+icon('log')+'</div><h2>مساحة جديدة، وسجل واضح</h2><p>ستظهر هنا عمليات هذه الجلسة بمجرد اتصالك بالسيرفر.</p></div>';}
function renderLogsOnly(){const box=$('#logList');if(box)box.innerHTML=logsMarkup();renderReportFiles();}

$$('[data-page]').forEach(button=>button.onclick=()=>go(button.dataset.page));$('#serverSwitch').onclick=()=>go('settings');$('#settingsShortcut').onclick=()=>go('settings');$('#refreshButton').onclick=()=>action('inventory');$('.brand').onclick=e=>{e.preventDefault();go('overview');};$('#confirmDialog').addEventListener('click',event=>{if(event.target===$('#confirmDialog'))$('#confirmDialog').close();});
window.addEventListener('pagehide',()=>{fetch('/api/action',{method:'POST',keepalive:true,headers:{'X-Cortex-Key':apiKey,'Content-Type':'application/json'},body:JSON.stringify({action:'client-closed',config:{}})}).catch(()=>{});});
render();pollState();setInterval(()=>pollState(),1200);
